/**
 * FreeODwiki-shaped Markdown export.
 *
 * Turns finished translation artifacts into a directory tree a FreeODwiki
 * maintainer copies in wholesale (github.com/SalviaSWC/FreeODwiki, rendered at
 * freeodwiki.org). That repository's root is its docs root, so the trees this
 * writes are named exactly as they land there: `药物/`, `药效/`, `报告/`,
 * `文档/`. Navigation is glob-generated by `.nav.yml` (mkdocs-awesome-nav), so
 * a new page publishes itself; the three curated index pages are hand-written
 * upstream and get paste-ready snippets under `_patches/` instead.
 *
 * Usage:
 *   node scripts/translation/export-freeodwiki.mjs --locale zh-Hans
 *
 * Options:
 *   --locale=<code>    Locale of the artifacts to read. Default zh-Hans.
 *   --root=<dir>       Artifact root. Default notes-and-plans/exports/translation/<locale>.
 *                      With --locale en, pass the translated locale's root: the English
 *                      source sits beside each translated artifact as source-export.json.
 *   --out=<dir>        Output tree. Default <root>/freeodwiki.
 *   --corpus=<a,b>     Restrict to these corpora. Default every exportable one.
 *   --help
 */

import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { parseArgs } from "node:util";
import { fileURLToPath } from "node:url";

import { CORPUS_ORDER, DATASET_OF, labelsFor } from "./freeodwiki-shape.mjs";
import { buildRegistry, fileNameFor, linkSafe } from "./freeodwiki-markdown.mjs";
import { articlePage, effectCategoryPage, effectPage, reportPage, substancePage, summaryPage } from "./freeodwiki-pages.mjs";

const repoRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");

// ------------------------------------------------------------- index patches

function patchFile({ tree, heading, note, lines, labels }) {
  return [
    `<!-- ${labels.ui.patchPreamble(tree)} -->`,
    `<!-- ${note} -->`,
    "",
    heading,
    "",
    ...lines,
    "",
  ].join("\n");
}

// -------------------------------------------------------------------- run

function newCounters() {
  return {
    internalLinksSeen: 0,
    internalLinksRewritten: 0,
    internalLinksDropped: 0,
    danglingTargetsBlocked: 0,
    mediaDropped: 0,
    citationMarkersStripped: 0,
    citationsDropped: 0,
    effectNamesLinked: 0,
  };
}

const BANNER_TONE_ORDER = ["danger", "unsafe", "caution"];
const MAX_BANNERS_PER_PAGE = 2;
const MARKDOWN_LINK = /\]\((\/[^)\s]+)\)/g;

/**
 * Nothing leaves this exporter pointing at a path their build cannot serve.
 * The four index pages are the only targets not written by this run, and they
 * are verified present on their `main` tree.
 */
function verifyLinks(pages, labels) {
  const written = new Set(pages.map((page) => `/${page.tree}/${linkSafe(page.file)}`));
  for (const tree of Object.values(labels.TREE)) written.add(`/${tree}/index.md`);

  const violations = [];
  let checked = 0;
  for (const page of pages) {
    for (const match of page.text.matchAll(MARKDOWN_LINK)) {
      checked += 1;
      const target = match[1];
      if (labels.DANGLING_TARGET_PREFIXES.some((prefix) => target.startsWith(prefix))) {
        violations.push(`${page.tree}/${page.file} -> ${target} (known dangling in the target repository)`);
        continue;
      }
      if (!written.has(target)) violations.push(`${page.tree}/${page.file} -> ${target}`);
    }
  }
  return { checked, violations };
}

async function readArtifact(root, corpusId, locale) {
  const dataset = DATASET_OF[corpusId];
  const candidates = [
    path.join(root, corpusId, `${dataset}.${locale}.json`),
    path.join(root, `${dataset}.${locale}.json`),
    // The English side is the source every translation was made from; it
    // lives beside the translated artifact under the corpus directory.
    ...(locale === "en" ? [path.join(root, corpusId, "source-export.json")] : []),
  ];
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(await readFile(candidate, "utf8"));
      return { artifact: parsed, file: candidate };
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
    }
  }
  return { artifact: null, file: null, tried: candidates };
}

/**
 * Paths that already exist in the target repository, so a maintainer copying
 * a tree in wholesale learns which of their own pages a copy would replace.
 * Accepts the GitHub trees API response or a newline-delimited path list; the
 * run stays offline, and skips the check when no listing is supplied.
 */
async function readUpstreamPaths(file) {
  const text = await readFile(path.resolve(repoRoot, file), "utf8");
  try {
    const parsed = JSON.parse(text);
    const entries = Array.isArray(parsed) ? parsed : parsed.tree;
    if (Array.isArray(entries)) {
      return new Set(entries
        .map((entry) => (typeof entry === "string" ? entry : entry?.path))
        .filter((entry) => typeof entry === "string"));
    }
  } catch {
    // Not JSON: a plain path list.
  }
  return new Set(text.split("\n").map((line) => line.trim()).filter(Boolean));
}

function main_help() {
  return [
    "node scripts/translation/export-freeodwiki.mjs --locale zh-Hans",
    "  --locale=<code>   Locale of the artifacts to read. Default zh-Hans.",
    "  --root=<dir>      Artifact root. Default notes-and-plans/exports/translation/<locale>.",
    "  --out=<dir>       Output tree. Default <root>/freeodwiki.",
    "  --corpus=<a,b>    Restrict to these corpora. Default substances,effects,articles,reports.",
    "  --upstream-tree=<file>  GitHub trees JSON or path list for the target repository.",
    "                          Supplying it reports which existing pages a copy would replace.",
  ].join("\n");
}

async function main() {
  const { values } = parseArgs({
    args: process.argv.slice(2),
    options: {
      locale: { type: "string", default: "zh-Hans" },
      root: { type: "string" },
      out: { type: "string" },
      corpus: { type: "string" },
      "upstream-tree": { type: "string" },
      help: { type: "boolean", default: false },
    },
    allowPositionals: false,
  });

  if (values.help) {
    console.log(main_help());
    return;
  }

  const locale = values.locale;
  const labels = labelsFor(locale);
  const root = values.root ? path.resolve(repoRoot, values.root) : path.join(repoRoot, "notes-and-plans/exports/translation", locale);
  const outDir = values.out ? path.resolve(repoRoot, values.out) : path.join(root, "freeodwiki");
  const wanted = values.corpus
    ? values.corpus.split(",").map((id) => id.trim()).filter(Boolean)
    : [...CORPUS_ORDER];

  for (const id of wanted) {
    if (!DATASET_OF[id]) throw new Error(`Unknown corpus "${id}". Exportable: ${CORPUS_ORDER.join(", ")}`);
  }

  console.log(`Locale        ${locale}`);
  console.log(`Artifacts     ${path.relative(repoRoot, root)}`);
  console.log(`Output        ${path.relative(repoRoot, outDir)}`);

  const found = [];
  const skipped = [];

  for (const id of wanted) {
    const { artifact, file, tried } = await readArtifact(root, id, locale);
    if (!artifact) {
      skipped.push({ corpus: id, reason: "artifact not found", tried: tried.map((candidate) => path.relative(repoRoot, candidate)) });
      continue;
    }
    const items = Array.isArray(artifact.items) ? artifact.items : [];
    found.push({ corpus: id, file, artifact, items, total: items.length });
  }

  for (const entry of found) {
    console.log(`Found         ${entry.corpus}: ${entry.total} records in ${path.relative(repoRoot, entry.file)}`);
  }
  for (const entry of skipped) {
    console.log(`Skipped       ${entry.corpus}: ${entry.reason} (${entry.tried.join(", ")})`);
  }


  // Identity first: a page body may link to a page written later in the run.
  const identities = [];
  for (const entry of found) {
    for (const item of entry.items) {
      const kind = { substances: "substance", effects: "effect", effectCategories: "effectCategory", articles: "article", summaries: "summary", reports: "report" }[entry.corpus];
      const title = String(kind === "effect" ? (item.name ?? item.slug) : (item.title ?? item.slug));
      // Summaries live in the article tree; their identity keeps the site path they answer to.
      const tree = labels.TREE[{ summary: "article", effectCategory: "effect" }[kind] ?? kind];
      identities.push({ kind, tree, slug: String(item.slug ?? ""), path: kind === "summary" ? String(item.path ?? "") : undefined, title, file: fileNameFor(title, String(item.slug ?? "page")) });
    }
  }
  const registry = buildRegistry(identities, labels);
  const effectPagesByTitle = new Map(identities
    .filter((identity) => identity.kind === "effect")
    .map((identity) => [identity.file.replace(/\.md$/, ""), `/${identity.tree}/${linkSafe(identity.file)}`]));
  const effectPagesBySlug = new Map(identities
    .filter((identity) => identity.kind === "effect")
    .map((identity) => [identity.slug, { title: identity.title, href: `/${identity.tree}/${linkSafe(identity.file)}` }]));

  // Banners are not a page corpus: they are chrome that belongs at the top of
  // the substance pages they are enabled on, in the locale being written.
  const bannerArtifact = (await readArtifact(root, "banners", locale)).artifact;
  const bannerPresets = (Array.isArray(bannerArtifact?.items) ? bannerArtifact.items : [])
    .filter((preset) => preset.enabled)
    .sort((a, b) => (BANNER_TONE_ORDER.indexOf(a.tone) - BANNER_TONE_ORDER.indexOf(b.tone)) || String(a.key).localeCompare(String(b.key)));
  const bannersFor = (slug) => bannerPresets.filter((preset) => (preset.enabledSlugs ?? []).includes(slug)).slice(0, MAX_BANNERS_PER_PAGE);
  console.log(`Banners       ${bannerPresets.length} presets${bannerArtifact ? "" : " (none found)"}`);

  const counters = newCounters();
  const pages = [];
  const emitted = {};

  for (const entry of found) {
    const build = {
      substances: substancePage,
      effects: effectPage,
      articles: articlePage,
      summaries: summaryPage,
      effectCategories: effectCategoryPage,
      reports: reportPage,
    }[entry.corpus];

    for (const item of entry.items) {
      const citations = new Map();
      const citationsById = new Map();
      for (const [index, citation] of (Array.isArray(item.citations) ? item.citations : []).entries()) {
        const id = String(citation?.from ?? index + 1);
        const record = { id, text: citation?.text ?? citation?.name ?? "", url: citation?.url ?? "" };
        citations.set(id, record);
        citationsById.set(id, record);
      }
      for (const reference of Array.isArray(item.references) ? item.references : []) {
        if (!reference?.id) continue;
        const record = { id: String(reference.id), text: reference.title ?? reference.apaText ?? "", url: reference.url ?? "" };
        citations.set(record.id, record);
        citationsById.set(record.id, record);
      }

      const ctx = {
        labels,
        registry,
        counters,
        citations,
        citationsById,
        citationOrder: new Map(),
        anchorPrefix: `ref-${String(item.slug ?? "page").replace(/[^\w-]/g, "-")}`,
        subarticleTitles: new Map((Array.isArray(item.subarticles) ? item.subarticles : [])
          .map((sub) => [String(sub?.id), String(sub?.title ?? sub?.id ?? "")])),
        effectPagesByTitle,
        effectPagesBySlug,
        generatedAt: entry.artifact.generatedAt,
        bannersFor,
      };

      const page = build(item, ctx);
      page.corpus = entry.corpus;
      page.slug = String(item.slug ?? "");
      pages.push(page);
      emitted[page.tree] = (emitted[page.tree] ?? 0) + 1;
    }
  }

  const verification = verifyLinks(pages, labels);
  if (verification.violations.length > 0) {
    for (const violation of verification.violations.slice(0, 20)) console.error(`  unresolvable link: ${violation}`);
    throw new Error(`${verification.violations.length} emitted links do not resolve inside the target tree`);
  }

  await rm(outDir, { recursive: true, force: true });
  for (const page of pages) {
    const target = path.join(outDir, page.tree, page.file);
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, page.text);
  }

  // Patch snippets for the hand-curated index pages `.nav.yml` does not glob.
  const patchDir = path.join(outDir, "_patches");
  await mkdir(patchDir, { recursive: true });
  const patches = [];
  const patchSpecs = Object.entries(labels.ui.patches).map(([kind, spec]) => ({ tree: labels.TREE[kind], ...spec }));
  for (const spec of patchSpecs) {
    const lines = pages
      .filter((page) => page.tree === spec.tree)
      .map((page) => `- [${page.file.replace(/\.md$/, "")}](/${spec.tree}/${linkSafe(page.file)})`)
      .sort((a, b) => a.localeCompare(b));
    if (lines.length === 0) continue;
    const file = path.join(patchDir, `${spec.tree}-index.patch.md`);
    await writeFile(file, patchFile({ ...spec, lines, labels }));
    patches.push({ file: path.relative(outDir, file), entries: lines.length });
  }

  const upstream = values["upstream-tree"] ? await readUpstreamPaths(values["upstream-tree"]) : null;
  const collisions = upstream
    ? pages.map((page) => `${page.tree}/${page.file}`).filter((target) => upstream.has(target))
    : null;

  const report = {
    locale,
    generatedAt: new Date().toISOString(),
    target: "github.com/SalviaSWC/FreeODwiki",
    targetLicense: "CC BY-SA 4.0",
    artifactRoot: path.relative(repoRoot, root),
    out: path.relative(repoRoot, outDir),
    corporaFound: found.map((entry) => ({ corpus: entry.corpus, records: entry.total, emitted: entry.items.length, artifact: path.relative(repoRoot, entry.file) })),
    corporaSkipped: skipped,
    filesEmitted: emitted,
    filesTotal: pages.length,
    /** Every emitted page, so a consumer can find the file for a record without re-deriving the name. */
    pages: pages.map((page) => ({ corpus: page.corpus, slug: page.slug, path: `${page.tree}/${page.file}` })),
    patches,
    counters,
    linkTargetsVerified: verification.checked,
    upstreamTree: values["upstream-tree"] ?? null,
    upstreamCollisions: collisions,
  };
  await writeFile(path.join(outDir, "export-report.json"), `${JSON.stringify(report, null, 2)}\n`);

  console.log("\nFiles emitted");
  for (const [tree, count] of Object.entries(emitted)) console.log(`  ${tree}/${" ".repeat(Math.max(0, 12 - tree.length))}${count}`);
  for (const patch of patches) console.log(`  ${patch.file} (${patch.entries} entries)`);
  console.log("\nLinks");
  console.log(`  internal seen         ${counters.internalLinksSeen}`);
  console.log(`  rewritten into tree   ${counters.internalLinksRewritten}`);
  console.log(`  dropped to plain text ${counters.internalLinksDropped}`);
  console.log(`  dangling blocked      ${counters.danglingTargetsBlocked} (${labels.DANGLING_TARGET_PREFIXES.join(", ")})`);
  console.log(`  link targets verified ${verification.checked}`);
  console.log("\nOther");
  console.log(`  media embeds dropped  ${counters.mediaDropped}`);
  console.log(`  cite markers stripped ${counters.citationMarkersStripped}`);
  console.log(`  refs without source   ${counters.citationsDropped}`);
  console.log(`  effect names linked   ${counters.effectNamesLinked}`);
  if (collisions) {
    console.log(`  pages already upstream ${collisions.length} of ${pages.length} would be replaced by a wholesale copy`);
    for (const collision of collisions.slice(0, 5)) console.log(`    ${collision}`);
    if (collisions.length > 5) console.log(`    ... ${collisions.length - 5} more, listed in export-report.json`);
  } else {
    console.log("  pages already upstream unchecked; pass --upstream-tree to compare against the target repository");
  }
  console.log(`  report                ${path.relative(repoRoot, path.join(outDir, "export-report.json"))}`);
}

if (import.meta.url === `file://${process.argv[1]}`) {
  main().catch((error) => {
    console.error(error?.stack ?? error?.message ?? error);
    process.exit(1);
  });
}

